// timeLayouts are the text layouts SQLite drivers commonly emit for
// timestamp columns, tried in order when scanning into a time.Time field.
var timeLayouts = []string{time.RFC3339Nano, time.RFC3339, "2006-01-02 15:04:05.999999999Z07:00", "2006-01-02 15:04:05.999999999", "2006-01-02T15:04:05", "2006-01-02 15:04:05", "2006-01-02"}

func (s *nullSafeField) Scan(value any) error {
	if value == nil {
		return nil
	}
	if s.target.Kind() == reflect.Pointer {
		elemPtr := reflect.New(s.target.Type().Elem())
		inner := &nullSafeField{target: elemPtr.Elem()}
		err_32 := inner.Scan(value)
		if err_32 != nil {
			return err_32
		}
		s.target.Set(elemPtr)
		return nil
	}
	if s.target.Kind() == reflect.Bool {
		if v, _isOk := value.(int64); _isOk {
			s.target.SetBool(v != 0)
			return nil
		}
		if v, _isOk := value.(int); _isOk {
			s.target.SetBool(v != 0)
			return nil
		}
	}
	if s.target.Kind() == reflect.String {
		s.target.SetString(cast.ToString(value))
		return nil
	}
	if bytes, _isOk := value.([]byte); _isOk {
		value = append([]byte{}, bytes...)
	}
	if s.target.Type() == timeType {
		if t, _isOk := value.(time.Time); _isOk {
			s.target.Set(reflect.ValueOf(t))
			return nil
		}
		if n, _isOk := value.(int64); _isOk {
			s.target.Set(reflect.ValueOf(time.Unix(n, 0).UTC()))
			return nil
		}
		if n, _isOk := value.(int); _isOk {
			s.target.Set(reflect.ValueOf(time.Unix(int64(n), 0).UTC()))
			return nil
		}
		if str, _isOk := value.(string); _isOk {
			return scanTimeString(s, str)
		}
		if b, _isOk := value.([]byte); _isOk {
			return scanTimeString(s, string(b))
		}
	}
	src := reflect.ValueOf(value)
	if src.Type().ConvertibleTo(s.target.Type()) {
		s.target.Set(src.Convert(s.target.Type()))
	} else {
		if s.target.Kind() == reflect.String {
			s.target.SetString(fmt.Sprintf("%v", value))
		} else {
			return fmt.Errorf("db: cannot convert %v to %v", src.Type(), s.target.Type())
		}
	}
	return nil
}

// scanTimeString parses str into s.target (a time.Time field) trying each
// common SQLite timestamp layout in order.
func scanTimeString(s *nullSafeField, str string) error {
	for _, layout := range timeLayouts {
		parsed, err := time.Parse(layout, str)
		if err == nil {
			s.target.Set(reflect.ValueOf(parsed))
			return nil
		}
	}
	return fmt.Errorf("db: cannot parse \"%v\" as time.Time", str)
}

// orderedFieldScanners creates null-safe scanners for all exported struct fields
// in declaration order. Used by ScanRow where column names aren't available from sql.Row.
func orderedFieldScanners(elem reflect.Value, elemType reflect.Type) []any {
	numFields := elemType.NumField()
	scanners := make([]any, 0, numFields)
	for i := range numFields {
		field := elemType.Field(i)
		if field.IsExported() {
			scanners = append(scanners, &nullSafeField{target: elem.Field(i)})
		}
	}
	return scanners
}

// camelToSnake converts CamelCase to snake_case. An uppercase run followed
// by a lowercase letter is one acronym segment: SourceURL → source_url,
// APIKey → api_key, JSONPayload → json_payload. A fully-capitalized name
// folds to a single lowercase segment (HTMLURL → htmlurl) — inherently
// ambiguous; the json-tag map is the disambiguator for such fields.
// (Insert the separator before an uppercase letter when the previous rune
// is lowercase — the word boundary — or the next rune is lowercase — the
// acronym run ending; consecutive uppercase letters stay glued.)
func camelToSnake(s string) string {
	runes := []rune{}
	for _, c := range s {
		runes = append(runes, c)
	}
	result := ""
	for i, r := range runes {
		if unicode.IsUpper(r) {
			lower := strpkg.ToLower(string(r))
			prevLower := i > 0 && unicode.IsLower(runes[i-1])
			nextLower := i+1 < len(runes) && unicode.IsLower(runes[i+1])
			if i > 0 && (prevLower || nextLower) {
				result = result + "_"
			}
			result = result + lower
		} else {
			result = result + string(r)
		}
	}
	return result
}

// QuoteIdentifier wraps a SQL identifier in double quotes and escapes any
// embedded double quotes. Use it for identifiers (table/column names) that
// cannot be parameterized — never for values, which must go through placeholders.
// Example: db.Query(pool, "SELECT * FROM {db.QuoteIdentifier(table)}")
func QuoteIdentifier(name string) string {
	return "\"" + strpkg.ReplaceAll(name, "\"", "\"\"") + "\""
}

// Like escapes LIKE wildcards (\\ % _) in pattern and wraps it in %...% for a
// contains match. Bind the result as a parameter alongside an ESCAPE clause:
//
//	db.Query(pool, "SELECT * FROM users WHERE name LIKE ? ESCAPE '\\'", db.Like(search))
//
// Example: db.Like("50%_off") → "%50\\%\\_off%"
func Like(pattern string) string {
	escaped := strpkg.ReplaceAll(pattern, "\\", "\\\\")
	escaped = strpkg.ReplaceAll(escaped, "%", "\\%")
	escaped = strpkg.ReplaceAll(escaped, "_", "\\_")
	return "%" + escaped + "%"
}

// In returns a parenthesized list of n '?' placeholders for an IN clause
// ('?'-style drivers: SQLite, MySQL). Pass the matching values as arguments.
// Example: db.Query(pool, "SELECT * FROM users WHERE id IN " + db.In(len(ids)), many ids)
func In(n int) string {
	if n <= 0 {
		return "()"
	}
	placeholders := make([]string, n)
	for i := range n {
		placeholders[i] = "?"
	}
	return "(" + strpkg.Join(placeholders, ", ") + ")"
}
